selected.compute:
options = read('/input/options')
ids = []
for option in options:
    ids = ids + [option['id']]
result = []
for count in range(goal['min_count'], goal['max_count'] + 1):
    for choice in combinations(ids, count):
        candidate = list(choice)
        if valid(candidate):
            result = candidate
            break
    if len(result) > 0:
        break

selected.effects:
artifact = read('/output/selection')
if artifact:
    selection = artifact
else:
    selection = result
    write('/output/selection', selection)
if status('report') == 'not_sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')
